            background: #f8fbfe;
            border-radius: 1rem;
            padding: 2rem 1.5rem;
            text-align: center;
            color: #7e97ae;
            font-style: italic;
            border: 1px dashed #c9dcec;
            margin: 0.5rem 0 1.5rem 0;
        }

        .add-note-form {
            margin-top: auto;
            background: #f9fcff;
            border-radius: 1.5rem;
            padding: 1.25rem 1.25rem 1rem 1.25rem;
            border: 1px solid #dee9f2;
            box-shadow: 0 4px 12px rgba(0, 20, 30, 0.04);
        }

        .add-note-form textarea {
            width: 100%;
            border: 1px solid #cfddee;
            border-radius: 1rem;
            padding: 0.9rem 1rem;
            font-family: inherit;
            font-size: 0.95rem;
            resize: vertical;
            min-height: 85px;
            background: white;
            color: #1d3e5c;
            transition: 0.1s;
        }

        .add-note-form textarea:focus {
            outline: none;
            border-color: #2b6f9e;
            box-shadow: 0 0 0 3px rgba(43, 111, 158, 0.15);
        }

        .form-actions {
            display: flex;
            justify-content: flex-end;
