            font-weight: 500;
            padding: 0.7rem 1.8rem;
            border: none;
            border-radius: 40px;
            font-size: 0.9rem;
            cursor: pointer;
            transition: 0.15s;
            display: flex;
            align-items: center;
            gap: 0.4rem;
            box-shadow: 0 4px 10px -2px rgba(28, 78, 117, 0.3);
        }

        .btn-primary:hover {
            background: #144b71;
            transform: translateY(-1px);
        }

        .btn-primary:active {
            transform: translateY(0);
        }

        /* small helpers */
        .disabled-message {
            color: #b1c7db;
            font-size: 0.9rem;
