<body>
<div class="app-container">
    <div class="app-header">
        <h1>
            🧑‍⚕️ PhysioNotes
            <span>clinic</span>
        </h1>
        <p>Write and review visit notes for each patient — simple, fast, private.</p>
    </div>

    <div class="main-panel">
        <!-- PATIENT SIDEBAR -->
        <div class="patient-sidebar">
            <h2>
                Patients
                <span class="patient-count" id="patientCount">3</span>
            </h2>
            <ul class="patient-list" id="patientList">
                <!-- dynamically filled by JS -->
            </ul>
            <div class="add-patient-btn" id="addPatientBtn">
                <span>+</span> New patient
            </div>
        </div>

        <!-- MAIN CONTENT (notes area) -->
        <div class="content-area" id="contentArea">
            <!-- dynamically rendered by JS -->
        </div>
    </div>
</div>

<script>
    (function() {
        // ---------- DATA ----------
        let patients = [
            {
                id: 'p1',
                name: 'Emma Rodriguez',
                notes: [
                    { text: 'Initial assessment: lower back pain, limited flexion. Started gentle mobility exercises.', date: '2025-03-10' },
                    { text: 'Improved range of motion. Added core stability exercises. Patient reports 40% less pain.', date: '2025-03-17' },
                ]
            },
            {
                id: 'p2',
                name: 'James Chen',
                notes: [
                    { text: 'Post-op knee rehab (ACL). Focus on quad activation and gentle ROM. No swelling.', date: '2025-03-12' },
                ]
            },
            {
                id: 'p3',
                name: 'Sophia Patel',
                notes: []
            }
        ];

        // currently selected patient id
        let selectedPatientId = 'p1';   // default

        // ---------- DOM references ----------
        const patientListEl = document.getElementById('patientList');
        const patientCountEl = document.getElementById('patientCount');
        const contentArea = document.getElementById('contentArea');
        const addPatientBtn = document.getElementById('addPatientBtn');

        // ---------- helper: generate short date ----------
        function getTodayDate() {
            const d = new Date();
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        // ---------- render patient list sidebar ----------
        function renderPatientList() {
            // update count
            patientCountEl.textContent = patients.length;

            // clear list
            patientListEl.innerHTML = '';

            if (patients.length === 0) {
                patientListEl.innerHTML = '<li class="disabled-message" style="list-style:none; padding:1rem;">No patients yet.<br>Click "New patient" below.</li>';
                return;
            }

            patients.forEach(patient => {
                const li = document.createElement('li');
                li.className = `patient-item ${selectedPatientId === patient.id ? 'active' : ''}`;
                li.dataset.patientId = patient.id;

                const nameSpan = document.createElement('span');
                nameSpan.className = 'patient-name';
                nameSpan.textContent = patient.name;

                const badge = document.createElement('span');
                badge.className = 'visit-badge';
                const noteCount = patient.notes.length;
                badge.textContent = noteCount === 1 ? '1 visit' : `${noteCount} visits`;

                li.appendChild(nameSpan);
                li.appendChild(badge);

                li.addEventListener('click', () => {
                    if (selectedPatientId !== patient.id) {
                        selectedPatientId = patient.id;
                        renderPatientList();      // update active highlight
                        renderMainContent();       // show notes for that patient
                    }
                });

                patientListEl.appendChild(li);
            });
        }

        // ---------- render main content (notes + form) ----------
        function renderMainContent() {
            // find selected patient
            const patient = patients.find(p => p.id === selectedPatientId);

            if (!patient) {
                // fallback: if no patient selected (e.g., after deletion, but we don't have deletion)
                // pick first patient or show empty
                if (patients.length > 0) {
                    selectedPatientId = patients[0].id;
                    renderPatientList();
                    renderMainContent();
                } else {
                    contentArea.innerHTML = `
                        <div class="empty-notes" style="margin-top:2rem;">
                            👋 No patients yet. Click "New patient" to get started.
                        </div>
                    `;
                }
                return;
            }

            // Build HTML for notes area
            let notesHtml = '';
            if (patient.notes.length === 0) {
                notesHtml = `<div class="empty-notes">📝 No visit notes yet. Add your first note below.</div>`;
            } else {
                // sort notes by date descending (newest first) — but we want to keep as is.
                // we can optionally sort, but we keep insertion order, but may sort by date.
                // For clarity, newest first:
                const sortedNotes = [...patient.notes].sort((a, b) => (a.date < b.date ? 1 : -1));
                const notesList = sortedNotes.map(note => {
                    const dateStr = note.date || 'unknown';
                    return `
                        <li class="note-item">
                            <div class="note-header">
                                <span>📅 ${dateStr}</span>
                            </div>
                            <div class="note-text">${escapeHtml(note.text)}</div>
                        </li>
                    `;
                }).join('');
                notesHtml = `<ul class="notes-list">${notesList}</ul>`;
            }

            // full content with patient header, notes, and form
            contentArea.innerHTML = `
                <div class="patient-header">
                    <h2>${escapeHtml(patient.name)}</h2>
                    <div class="patient-meta">${patient.notes.length} visit${patient.notes.length !== 1 ? 's' : ''}</div>
                </div>
                <div class="notes-section">
                    ${notesHtml}
                    <div class="add-note-form">
                        <textarea id="noteInput" placeholder="Write your visit note here… e.g. 'Manual therapy, exercises, patient reports improvement.'" rows="3"></textarea>
                        <div class="form-actions">
                            <button class="btn-primary" id="saveNoteBtn">
                                <span>+</span> Save note
                            </button>
                        </div>
                    </div>
                </div>
            `;

            // attach event to save button
            const saveBtn = document.getElementById('saveNoteBtn');
            const noteInput = document.getElementById('noteInput');
            if (saveBtn && noteInput) {
                saveBtn.addEventListener('click', () => {
                    const noteText = noteInput.value.trim();
                    if (noteText === '') {
                        alert('Please write a note before saving.');
                        return;
                    }

                    // add note with today's date
                    const today = getTodayDate();
                    patient.notes.push({ text: noteText, date: today });

                    // re-render sidebar (to update badge count)
                    renderPatientList();
                    // re-render main content (clears textarea, shows new note)
                    renderMainContent();
                });

                // optional: allow Ctrl+Enter to save
                noteInput.addEventListener('keydown', (e) => {
                    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                        e.preventDefault();
                        saveBtn.click();
                    }
                });
            }
        }

        // tiny escape for HTML safety
        function escapeHtml(unsafe) {
            if (!unsafe) return '';
            return unsafe
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        }

        // ---------- add new patient ----------
        function addNewPatient() {
            const patientName = prompt('Enter the new patient\'s full name:');
            if (!patientName || patientName.trim() === '') return;

            const newId = 'p' + Date.now() + Math.random().toString(36).substring(2, 8);
            patients.push({
                id: newId,
                name: patientName.trim(),
                notes: []
            });

            // select the new patient
            selectedPatientId = newId;

            // re-render everything
            renderPatientList();
            renderMainContent();
        }

        // ---------- initial render ----------
        function init() {
            // make sure selectedPatientId exists, otherwise choose first
            if (!patients.some(p => p.id === selectedPatientId)) {
                if (patients.length > 0) {
                    selectedPatientId = patients[0].id;
                } else {
                    selectedPatientId = null;
                }
            }

            renderPatientList();
            renderMainContent();

            // add patient event
            addPatientBtn.addEventListener('click', addNewPatient);
        }

        // start the app
        init();

        // optional: handle if patient list becomes empty (not needed with current no-delete)
    })();
</script>
</body>
</html>
